// Generated by vibelang from src/components/markdown-projection.ts; the migrate flow writes it again with each batch.
export function completedProjection(text) {
    return { text, blocks: [{ raw: text, src: text, mode: "full" }] };
}
export function canReusePendingBlock(current, next) {
    if (!current || current.mode !== next.mode)
        return false;
    if (next.mode === "code" || next.mode === "live")
        return next.raw.startsWith(current.raw);
    return current.raw === next.raw;
}
